-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeCLGauge.json. Do not edit: change the chain file or ABI and regenerate.
-- ClaimRewards(address,uint256)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_cl_gauge__claim_rewards',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as from,
    reinterpretAsUInt256(reverse(unhex(substring(data, 3, 64)))) as amount
from {{ source('chain_base', 'logs') }}
where topic0 = '0x1f89f96333d3133000ee447473151fa9606543368f02271c9d95ae14f13bcc67'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_cl_gauge')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
